$_SESSION['usuario_nome']=$me['nm_usuario'];$_SESSION['usuario_tipo']=$me['tp_usuario'];$ehAdmin=strcasecmp(trim($me['tp_usuario']),'Administrador')===0;$canCreate=$ehAdmin||!empty($me['is_community_user']);if(empty($_SESSION['social_csrf']))$_SESSION['social_csrf']=bin2hex(random_bytes(24));
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Chats | LibrasHub</title><link rel="icon" href="../static/images/librashub-logo.png"><link rel="stylesheet" href="../static/css/style.css"><link rel="stylesheet" href="../static/css/app-shell.css"><link rel="stylesheet" href="../static/css/sidebar.css"><link rel="stylesheet" href="../static/css/social.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.7.2/css/all.min.css"></head><body class="app-shell app-dashboard social-page">
<?php $sidebarId='sidebarMenu';include __DIR__.'/partials/sidebar.php';?>
<main class="content" id="conteudo-principal"><div class="social-layout"><aside class="social-left"><div class="social-brand"><div class="social-brand__row"><div><h1>Chats</h1></div><?php if($canCreate):?><button class="icon-button" id="createCommunity" aria-label="Criar comunidade" title="Criar comunidade"><i class="fa-solid fa-plus"></i></button><?php endif;?></div><a class="chat-feed-link" href="social.php"><i class="fa-solid fa-arrow-left"></i>Voltar para o feed</a><div class="social-search"><i class="fa-solid fa-magnifying-glass"></i><input id="globalSearch" type="search" placeholder="Nome da comunidade ou pessoa" aria-label="Buscar comunidade ou usuário por nome"><div class="search-results" id="searchResults"></div></div></div><div class="social-tabs" role="tablist"><button class="social-tab is-active" data-list="communities">Comunidades</button><button class="social-tab" data-list="private">Chats privados</button></div><div class="social-list" id="socialList"></div></aside>
<section class="social-main"><header class="social-toolbar"><div class="social-toolbar__title"><button class="icon-button social-back" id="chatBack" hidden aria-label="Voltar"><i class="fa-solid fa-arrow-left"></i></button><h2 id="chatTitle">Comunidades</h2></div></header><div class="social-content"><div class="social-welcome is-active" id="welcome"><div class="social-welcome__inner"><div class="social-welcome__icon"><i class="fa-solid fa-comments"></i></div><h2>Suas conversas em um só lugar.</h2><p>Escolha uma comunidade ou inicie um chat privado.</p></div></div><div class="chat-view" id="chatView"><div class="messages" id="messages" aria-live="polite"></div><form class="composer" id="messageForm"><div class="media-menu"><label class="icon-button" title="Enviar imagem"><i class="fa-solid fa-image"></i><input id="imageInput" type="file" accept="image/jpeg,image/png,image/webp,image/gif" hidden></label><label class="icon-button" title="Enviar figurinha"><i class="fa-solid fa-note-sticky"></i><input id="stickerInput" type="file" accept="image/png,image/webp,image/gif" hidden></label></div><textarea id="messageText" rows="1" maxlength="4000" placeholder="Escreva uma mensagem" aria-label="Mensagem"></textarea><button class="icon-button composer-send" aria-label="Enviar"><i class="fa-solid fa-paper-plane"></i></button></form></div><div class="community-view" id="communityView"></div></div></section></div></main>
<div class="social-dialog" id="communityDialog" role="dialog" aria-modal="true" aria-labelledby="communityDialogTitle"><form class="social-dialog__card ui-card social-form" id="communityForm"><div class="social-dialog__head"><h2 id="communityDialogTitle">Criar comunidade</h2><button type="button" class="icon-button" data-close aria-label="Fechar"><i class="fa-solid fa-xmark"></i></button></div><div class="ui-field"><label for="communityName">Nome</label><input id="communityName" name="name" maxlength="100" required></div><div class="ui-field"><label for="communityDescription">Descrição</label><textarea id="communityDescription" name="description" minlength="10" maxlength="500" required></textarea></div><label><input type="checkbox" name="private" value="1"> Comunidade privada</label><div id="communityStatus" role="status"></div><button class="ui-button">Criar comunidade</button></form></div>
<div class="social-dialog" id="editDialog" role="dialog" aria-modal="true" aria-labelledby="editDialogTitle"><form class="social-dialog__card ui-card social-form" id="editForm"><div class="social-dialog__head"><h2 id="editDialogTitle">Editar conteúdo</h2><button type="button" class="icon-button" data-close aria-label="Fechar"><i class="fa-solid fa-xmark"></i></button></div><div class="ui-field"><label for="editText">Texto</label><textarea id="editText" name="text" maxlength="4000"></textarea></div><div id="editStatus" role="status"></div><div class="dialog-actions"><button type="button" class="ui-button ui-button--secondary" data-close>Cancelar</button><button class="ui-button" type="submit">Salvar alterações</button></div></form></div>
<script>
const API='ajax/social_api.php',EVENTS='ajax/social_events.php',CSRF=<?= json_encode($_SESSION['social_csrf']) ?>,ME=<?= $uid ?>,REQUESTED_CHAT=Number(new URLSearchParams(location.search).get('chat')||0);let data={communities:[],chats:[]},tab=new URLSearchParams(location.search).get('tab')==='private'?'private':'communities',activeChat=0,source=null,timer,messageSync=null,openedRequestedChat=false;
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));async function api(action,opt={}){const r=await fetch(API+'?'+new URLSearchParams({action,...(opt.query||{})}),opt.fetch),j=await r.json().catch(()=>({ok:false,message:'Resposta inválida'}));if(!r.ok||!j.ok)throw new Error(j.message||'Falha');return j}let editContext=null;function openEditor(action,id,text,done){editContext={action,id,done};editDialogTitle.textContent=action==='edit_message'?'Editar mensagem':'Editar publicação';editText.value=text;editStatus.textContent='';editDialog.classList.add('is-open');setTimeout(()=>editText.focus(),0)}
function setView(id){['welcome','chatView','communityView'].forEach(x=>document.getElementById(x).classList.toggle('is-active',x===id));chatBack.hidden=id==='welcome';document.querySelector('.social-layout').classList.toggle('has-conversation',id!=='welcome')}chatBack.onclick=()=>{if(source)source.close();clearInterval(messageSync);source=null;messageSync=null;activeChat=0;chatTitle.textContent=tab==='private'?'Chats privados':'Comunidades';setView('welcome')};
async function overview(){try{data=await api('overview');if(REQUESTED_CHAT&&!openedRequestedChat){const requested=data.chats.find(c=>Number(c.id_chat)===REQUESTED_CHAT&&c.tipo==='privado');if(requested){openedRequestedChat=true;tab='private';renderList();await openChat(Number(requested.id_chat),requested.titulo||'Conversa privada');return}}renderList()}catch(e){socialList.innerHTML='<div class="social-empty">'+esc(e.message)+'</div>'}}function renderList(){document.querySelectorAll('.social-tab').forEach(x=>x.classList.toggle('is-active',x.dataset.list===tab));if(tab==='communities'){socialList.innerHTML=data.communities.length?data.communities.map(c=>`<button class="social-item" data-community="${c.id_comunidade}"><span class="social-avatar"><i class="fa-solid fa-users"></i></span><span class="social-item__body"><strong>${esc(c.nome)}</strong><small>${c.privada==1?'Privada':'Pública'} · ${c.membros} membros</small></span></button>`).join(''):'<div class="social-empty">Nenhuma comunidade encontrada.</div>'}else{const chats=data.chats.filter(c=>c.tipo==='privado');socialList.innerHTML=chats.length?chats.map(c=>`<button class="social-item" data-chat="${c.id_chat}"><span class="social-avatar"><i class="fa-solid fa-user"></i></span><span class="social-item__body"><strong>${esc(c.titulo||'Conversa privada')}</strong><small>Chat privado</small></span></button>`).join(''):'<div class="social-empty">Busque uma pessoa para iniciar uma conversa.</div>'}}
document.querySelector('.social-tabs').onclick=e=>{const b=e.target.closest('[data-list]');if(!b)return;tab=b.dataset.list;history.replaceState({},'',`chats.php?tab=${tab}`);chatTitle.textContent=tab==='private'?'Chats privados':'Comunidades';setView('welcome');renderList()};socialList.onclick=e=>{const c=e.target.closest('[data-community]'),p=e.target.closest('[data-chat]');if(c)openCommunity(c.dataset.community);if(p)openChat(Number(p.dataset.chat),p.querySelector('strong').textContent)};
function communityMedia(p){if(!p.midia_url)return '';return p.midia_tipo==='video'?`<video class="community-media" controls preload="metadata"><source src="${esc(p.midia_url)}"></video>`:`<img class="community-media" src="${esc(p.midia_url)}" alt="Mídia publicada por ${esc(p.nm_usuario)}" loading="lazy">`}
function renderCommunityPost(p){return `<article class="social-post ui-card" data-community-post="${Number(p.id_post)}"><div class="social-post__head"><a href="perfil.php?id=${Number(p.id_usuario)}">${esc(p.nm_usuario)}</a><time>${esc(p.criado_em)}${p.editado_em?' · editado':''}</time>${Number(p.id_usuario)===ME?'<button type="button" class="post-edit" data-edit-community-post aria-label="Editar publicação"><i class="fa-regular fa-pen-to-square"></i>Editar</button>':''}</div>${p.conteudo?`<p>${esc(p.conteudo)}</p>`:''}${communityMedia(p)}</article>`}
async function openCommunity(id){if(source)source.close();clearInterval(messageSync);source=null;messageSync=null;activeChat=0;const joined=await api('join_community',{fetch:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf:CSRF,id})}});if(joined.status==='pendente'){alert(joined.message);return}const j=await api('feed',{query:{community:id}}),c=data.communities.find(x=>x.id_comunidade==id)||j.community,canMedia=Number(c.id_criador)===ME;chatTitle.textContent=c.nome;setView('communityView');communityView.innerHTML=`<article class="community-hero ui-card"><h2>${esc(c.nome)}</h2><p>${esc(c.descricao)}</p></article><div class="community-post-list">${j.posts.map(renderCommunityPost).join('')||'<div class="social-empty">Nenhuma mensagem ainda.</div>'}</div><form class="post-composer post-composer--community ui-card" id="communityPost" enctype="multipart/form-data"><label for="communityMessage">Escrever na comunidade</label><textarea id="communityMessage" name="text" maxlength="4000" placeholder="Digite uma mensagem"></textarea><div class="post-composer__actions">${canMedia?'<label class="community-media-button"><i class="fa-regular fa-image"></i>Foto ou vídeo<input type="file" name="media" accept="image/jpeg,image/png,image/webp,video/mp4" hidden></label>':''}<span class="community-post-status" role="status"></span><button class="ui-button">Publicar</button></div></form>`;const communityForm=document.getElementById('communityPost');communityForm.onsubmit=async e=>{e.preventDefault();const status=e.target.querySelector('.community-post-status'),fd=new FormData(e.target);status.textContent='Publicando...';fd.append('csrf',CSRF);fd.append('community',id);try{await api('post',{fetch:{method:'POST',body:fd}});await openCommunity(id)}catch(error){status.textContent=error.message}};communityView.onclick=e=>{const button=e.target.closest('[data-edit-community-post]');if(!button)return;const post=button.closest('[data-community-post]'),current=post.querySelector('p')?.textContent||'';openEditor('edit_post',post.dataset.communityPost,current,()=>openCommunity(id))}}
async function openChat(id,title){activeChat=id;chatTitle.textContent=title;setView('chatView');messages.innerHTML='';if(source)source.close();clearInterval(messageSync);const j=await api('messages',{query:{chat:id}});j.messages.forEach(addMessage);source=new EventSource(EVENTS+'?'+new URLSearchParams({chat:id,after:lastMessage()}));source.addEventListener('message',e=>addMessage(JSON.parse(e.data)));messageSync=setInterval(async()=>{if(activeChat!==id)return;try{const current=await api('messages',{query:{chat:id}});if(activeChat===id)current.messages.forEach(addMessage)}catch(error){}},8000)}function lastMessage(){return Number(messages.lastElementChild?.dataset.id||0)}function addMessage(m){if(Number(m.id_chat)!==activeChat)return;let el=messages.querySelector(`[data-id="${m.id_mensagem}"]`);const mine=Number(m.id_usuario)===ME,body=`<div class="message-head"><strong>${esc(m.nm_usuario)}</strong>${mine&&m.texto?'<button type="button" data-edit-message aria-label="Editar mensagem"><i class="fa-solid fa-pen"></i></button>':''}</div>${m.anexo_url?`<img src="${esc(m.anexo_url)}" alt="${m.tipo_anexo==='sticker'?'Figurinha':'Imagem enviada'}">`:''}${m.texto?`<p>${esc(m.texto)}</p>`:''}<small class="message-time">${esc(m.criado_em||'')}${m.editado_em?' · editada':''}</small>`;if(el){el.innerHTML=body;return}el=document.createElement('article');el.className='message '+(mine?'is-mine ':'')+(m.tipo_anexo==='sticker'?'is-sticker':'');el.dataset.id=m.id_mensagem;el.innerHTML=body;messages.appendChild(el);messages.scrollTop=messages.scrollHeight}
messageForm.onsubmit=async e=>{e.preventDefault();if(!activeChat)return;const file=stickerInput.files[0]||imageInput.files[0],fd=new FormData();fd.append('csrf',CSRF);fd.append('chat',activeChat);fd.append('text',messageText.value);fd.append('kind',stickerInput.files[0]?'sticker':'imagem');if(file)fd.append('media',file);await api('send',{fetch:{method:'POST',body:fd}});messageText.value='';imageInput.value='';stickerInput.value=''};
messageText.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();messageForm.requestSubmit()}});messages.onclick=e=>{const button=e.target.closest('[data-edit-message]');if(!button)return;const message=button.closest('[data-id]'),current=message.querySelector('p')?.textContent||'';openEditor('edit_message',message.dataset.id,current,result=>{const paragraph=message.querySelector('p');if(paragraph)paragraph.textContent=result.text;const time=message.querySelector('.message-time');if(time&&!time.textContent.includes('editada'))time.textContent+=' · editada'})};
globalSearch.oninput=()=>{clearTimeout(timer);timer=setTimeout(async()=>{if(globalSearch.value.trim().length<2){searchResults.innerHTML='';return}const j=await api('search',{query:{q:globalSearch.value}});searchResults.innerHTML=[...j.communities.map(c=>`<button class="social-item" data-search-community="${c.id_comunidade}"><span class="social-item__body"><strong>${esc(c.nome)}</strong><small>Comunidade ${c.privada==1?'privada':'pública'}</small></span></button>`),...j.users.map(u=>`<button class="social-item" data-search-user="${u.id_usuario}" data-user-name="${esc(u.nm_usuario)}"><span class="social-avatar">${esc(u.nm_usuario?.[0]||'U')}</span><span class="social-item__body"><strong>${esc(u.nm_usuario)}</strong><small>Usuário do LibrasHub</small></span></button>`)].join('')},250)};searchResults.onclick=async e=>{const c=e.target.closest('[data-search-community]'),u=e.target.closest('[data-search-user]');if(c){tab='communities';renderList();openCommunity(c.dataset.searchCommunity)}if(u){const j=await api('start_private',{fetch:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf:CSRF,user:u.dataset.searchUser})}});tab='private';await overview();renderList();openChat(j.id,u.dataset.userName)}searchResults.innerHTML=''};
editForm.onsubmit=async e=>{e.preventDefault();if(!editContext)return;const submit=e.target.querySelector('[type="submit"]'),payload={csrf:CSRF,text:editText.value};payload[editContext.action==='edit_post'?'post':'message']=editContext.id;submit.disabled=true;editStatus.textContent='Salvando...';try{const result=await api(editContext.action,{fetch:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}}),done=editContext.done;editDialog.classList.remove('is-open');editContext=null;await done(result)}catch(error){editStatus.textContent=error.message}finally{submit.disabled=false}};
<?php if($canCreate):?>createCommunity.onclick=()=>communityDialog.classList.add('is-open');communityForm.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.csrf=CSRF;d.private=Boolean(d.private);try{await api('create_community',{fetch:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)}});e.target.reset();communityDialog.classList.remove('is-open');tab='communities';await overview()}catch(x){communityStatus.textContent=x.message}};<?php endif;?>document.addEventListener('click',e=>{const close=e.target.closest('[data-close]');if(close)close.closest('.social-dialog')?.classList.remove('is-open');if(e.target.classList.contains('social-dialog'))e.target.classList.remove('is-open')});document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.social-dialog.is-open').forEach(dialog=>dialog.classList.remove('is-open'))});overview();
</script><script src="../static/js/acessibility.js" defer></script></body></html>
